"""Keep a read-only hard link to each SST generated by one disposable load fixture."""

import argparse
import os
from pathlib import Path
import time


def capture(scratch, destination):
    for path in scratch.glob("*/evidence/stem-storage-*/node-*/db/*.sst"):
        target = destination / path.parents[2].name / path.parents[1].name / path.name
        target.parent.mkdir(parents=True, exist_ok=True)
        try:
            os.link(path, target)
        except (FileExistsError, FileNotFoundError):
            pass


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("scratch", type=Path)
    parser.add_argument("destination", type=Path)
    parser.add_argument("--seconds", type=int, required=True)
    args = parser.parse_args()
    end = time.monotonic() + args.seconds
    while time.monotonic() < end:
        capture(args.scratch, args.destination)
        time.sleep(0.5)
